// barbLib offline support.
//
// Install: caches the whole app, including the reader engines and PDF fonts
// (list in precache.json, generated by tools/release.py), so every format opens
// offline after the first launch.
// Requests: network first so updates show immediately, but if the network
// hasn't answered within 3 seconds (bad signal) the cached copy is used and the
// network answer still refreshes the cache in the background.
// Books themselves live in IndexedDB, not here.
const CACHE = 'barblib-1.0.2'
const TIMEOUT_MS = 3000
const FALLBACK_SHELL = ['./', 'index.html', 'css/app.css', 'manifest.webmanifest', 'js/app.js']

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE)
    let list = FALLBACK_SHELL
    try { list = await (await fetch('precache.json', { cache: 'no-cache' })).json() } catch { /* use fallback */ }
    // add one by one so a single missing file can't break the install
    await Promise.all(list.map(u => cache.add(new Request(u, { cache: 'no-cache' })).catch(() => {})))
    await self.skipWaiting()
  })())
})

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()))
})

self.addEventListener('fetch', e => {
  const { request } = e
  const url = new URL(request.url)
  if (request.method !== 'GET' || url.origin !== location.origin) return
  if (url.pathname.includes('/samples/') || url.pathname.endsWith('/version.json')) return

  e.respondWith((async () => {
    const cache = await caches.open(CACHE)
    const cached = await cache.match(request, { ignoreSearch: true })
      ?? (request.mode === 'navigate' ? await cache.match('index.html') ?? await cache.match('./') : undefined)

    const network = fetch(request, { cache: 'no-cache' }).then(res => {
      if (res.ok) cache.put(request, res.clone())
      return res
    })

    if (!cached) return network // nothing cached yet: wait for the network
    // keep the background refresh alive even if we answer from cache
    e.waitUntil(network.then(() => {}, () => {}))
    const timeout = new Promise(resolve => setTimeout(() => resolve(cached), TIMEOUT_MS))
    return Promise.race([network.catch(() => cached), timeout])
  })())
})
